<?php require __DIR__.'/bootstrap.php';$u=require_login();$plan=user_plan((int)$u['id']);$q=$pdo->prepare('SELECT COUNT(*) FROM webauthn_credentials WHERE user_id=?');$q->execute([$u['id']]);$passkeys=(int)$q->fetchColumn();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#060914"><link rel="manifest" href="manifest.json"><title>Minha conta — Arena de Aço</title><link rel="stylesheet" href="assets/app.css"><script defer src="pwa.js"></script><style>.passkey-panel{display:flex;justify-content:space-between;gap:18px;align-items:center}.passkey-panel small{display:block;color:#aab5c9;margin-top:6px;font-size:11px}.passkey-status{margin:10px 0 0;color:#70d6ff;font-size:11px}@media(max-width:650px){.passkey-panel{display:block}.passkey-panel .btn{margin-top:15px}}</style></head><body><?php nav($u)?><main class="dashboard"><p class="kicker">MINHA ARENA</p><h1><?=e($u['name'])?></h1><section class="panel"><h2>Seu acesso atual</h2><p class="bigplan"><?=strtoupper($plan)?></p><p class="muted">Você pode abrir chamados, conversar com a comunidade e assistir aos conteúdos incluídos no seu plano.</p><a class="btn" href="client_documents.php">Abrir biblioteca protegida</a> <a class="outline" href="community.php">Comunidade</a></section><section class="panel passkey-panel"><div><h2>Login por biometria</h2><small>Cadastre uma passkey para entrar usando digital, Face ID ou o bloqueio de tela do celular. Este dispositivo precisa estar em HTTPS.</small><p class="passkey-status" id="pk-status"><?=$passkeys?'Passkey cadastrada neste dispositivo.':'Nenhuma passkey cadastrada ainda.'?></p></div><button id="pk-register" class="btn" type="button"><?=$passkeys?'Cadastrar outra':'Ativar biometria'?></button></section><section class="panel"><h2>Assinatura e pagamento</h2><p class="muted">Escolha um plano. Com a chave Asaas configurada, o sistema cria a cobrança recorrente após os 7 dias grátis.</p><form action="asaas_checkout.php" method="post"><label>Plano<select name="plan"><option value="basic">Básico — R$ 9,90/mês</option><option value="premium">Premium — R$ 19,90/mês</option><option value="ultimate">Ultimate — R$ 29,90/mês</option></select></label><button class="btn">Ativar cobrança com Asaas →</button></form></section><?php if($plan==='ultimate'):?><section class="panel"><h2>Conteúdo Ultimate liberado</h2><p>Você possui acesso aos vídeos exclusivos.</p><a href="index.php#ultimate">Explorar vídeos</a></section><?php endif?></main><script>
const b64=s=>{s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return Uint8Array.from(atob(s),c=>c.charCodeAt(0));};const b64s=b=>{let s='';new Uint8Array(b).forEach(x=>s+=String.fromCharCode(x));return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};const st=document.querySelector('#pk-status');document.querySelector('#pk-register').onclick=async()=>{try{if(!window.PublicKeyCredential)throw Error('Seu navegador não oferece passkeys.');st.textContent='Aguardando digital, Face ID ou bloqueio de tela…';const start=await fetch('webauthn_register_begin.php');const data=await start.json();if(!start.ok)throw Error(data.error||'Não foi possível iniciar.');const p=data.publicKey;p.challenge=b64(p.challenge);p.user.id=b64(p.user.id);const cred=await navigator.credentials.create({publicKey:p});const body={id:cred.id,rawId:b64s(cred.rawId),type:cred.type,response:{clientDataJSON:b64s(cred.response.clientDataJSON),attestationObject:b64s(cred.response.attestationObject)}};const finish=await fetch('webauthn_register_finish.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await finish.json();if(!finish.ok)throw Error(result.error||'Não foi possível cadastrar.');st.textContent=result.message||'Biometria ativada.';}catch(e){st.textContent=e.message||'Operação cancelada.';}};
</script></body></html>
